package com.bank.antifraud;

import java.util.concurrent.*;

public class FraudScoringService {
    private final RuleEngine ruleEngine;
    private final MlModelClient mlClient;
    private final RedisFeatureStore redis;

    public FraudScoringService(RuleEngine ruleEngine, MlModelClient mlClient, RedisFeatureStore redis) {
        this.ruleEngine = ruleEngine;
        this.mlClient = mlClient;
        this.redis = redis;
    }

    public FraudDecision score(Transaction tx) {
        // BUG: Synchronous sequential calls exceed 100ms SLA when ML model lags
        // Must run rules + ML in parallel with CircuitBreaker and fallback to heuristic rules
        return null;
    }
}

